async function n(r){try{const e=await fetch("http://3.139.202.192:3000/api/public/contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)}),t=await e.json();return{ok:e.ok,message:t.message}}catch{return{ok:!1,message:"Error de conexión."}}}async function o(r){try{const t=await(await fetch("http://3.139.202.192:3000/api/contact",{headers:{Authorization:`Bearer ${r}`}})).json();return t.ok?t.data:[]}catch(e){return console.error("Error al obtener mensajes:",e),[]}}async function s(r,e){try{return(await fetch(`http://3.139.202.192:3000/api/contact/${r}`,{method:"DELETE",headers:{Authorization:`Bearer ${e}`}})).ok}catch{return!1}}async function c(r,e){try{const a=await(await fetch(`http://3.139.202.192:3000/api/contact/${r}`,{headers:{Authorization:`Bearer ${e}`}})).json();return a.ok?a.data:null}catch{return null}}export{s as a,c as b,n as e,o as g};
